SELECT COALESCE(SUM(num) / 6340.0, 0)
FROM tb_grid_permanent_num
WHERE population_type = 'HOME'
  AND city_code = #{cityCode}
  AND date = #{date}

SELECT COALESCE(SUM(num) / 6340.0, 0)
FROM tb_grid_permanent_num
WHERE population_type = 'WORK'
  AND city_code = #{cityCode}
  AND date = #{date}
